    ["lesson"] = {
      { "Life Tap taught me to pay for magic with my own health.", tags = { "spell:Life_Tap" } },
      { "Fear was a new way to put the terror on the other side of a fight.", tags = { "spell:Fear" } },
      { "Drain Life entered my repertoire, a hungry spell that could keep me alive at someone else's expense.", tags = { "spell:Drain_Life" } },
      { "Corruption was mine to use, slow enough to make a quick death seem generous.", tags = { "spell:Corruption" } },
      { "With Health Funnel learned, keeping a demon alive could now cost me my own health.", tags = { "spell:Health_Funnel" } },
      { "I learned Polymorph, and took an undignified comfort in the prospect of turning an enemy into a sheep.", tags = { "spell:Polymorph" } },
      { "Blink gave me a sudden affection for the distance a single spell could put between me and danger.", tags = { "spell:Blink" } },
      { "Frost Nova offered a way to let ice hold an enemy while I found somewhere safer to stand.", tags = { "spell:Frost_Nova" } },
      { "I learned to conjure water, and liked having one less ordinary need to carry along the road.", tags = { "spell:Conjure_Water" } },
      { "Power Word: Shield was a ward I could now set between myself and an enemy's blow.", tags = { "spell:Power_Word:_Shield" } },
      { "I took instruction in Renew, comforted by healing that could keep working after the prayer ended.", tags = { "spell:Renew" } },
      { "Resurrection gave me the frightening prospect of calling someone back instead of leaving a name to mourn.", tags = { "spell:Resurrection" } },
      { "Psychic Scream was mine to use, a way to make my fear someone else's problem.", tags = { "spell:Psychic_Scream" } },
      { "Lay on Hands gave me a fierce comfort in having something left to offer when an ordinary blessing would not be enough.", tags = { "spell:Lay_on_Hands" } },
      { "I learned Divine Protection, and liked the prospect of shelter made of Light.", tags = { "spell:Divine_Protection" } },
      { "Hammer of Justice offered a firm interruption to an enemy's intentions.", tags = { "spell:Hammer_of_Justice" } },
      { "With Charge learned, I could close the distance before my courage had time to argue about it.", tags = { "spell:Charge" } },
      { "I took instruction in Execute, with the ugly comfort of knowing how to finish a fight that had already cost enough.", tags = { "spell:Execute" } },
      { "Learning to pick pockets gave me a new sympathy for anyone who kept a hand on their purse.", tags = { "spell:Pick_Pocket" } },
      { "Sap offered the prospect of leaving an enemy unconscious instead of making an introduction.", tags = { "spell:Sap" } },
      { "Vanish was a new way to let an enemy wonder where its troubles had gone.", tags = { "spell:Vanish" } },
      { "I learned Sprint, and saw an excellent use for it in leaving trouble behind.", tags = { "spell:Sprint" } },
      { "Aspect of the Cheetah gave me a hunter's answer to a long road.", tags = { "spell:Aspect_of_the_Cheetah" } },
      { "Feign Death was a hunter's lie I could now tell to avoid becoming the truth of it.", tags = { "spell:Feign_Death" } },
      { "Hunter's Mark offered a way to keep my quarry from becoming merely another movement I could not place.", tags = { "spell:Hunter's_Mark" } },
      { "I learned Ghost Wolf, and could borrow a swifter shape from the spirits without leaving my life behind.", tags = { "spell:Ghost_Wolf" } },
      { "Ancestral Spirit brought the tender prospect of calling someone back before their place among us grew empty.", tags = { "spell:Ancestral_Spirit" } },
      { "Lightning Shield was mine to call on, thunder waiting for the hand that reached for me.", tags = { "spell:Lightning_Shield" } },
      { "Entangling Roots offered a way to hold an enemy without keeping it within my own reach.", tags = { "spell:Entangling_Roots" } },
      { "I took instruction in Healing Touch, grateful for a gentle answer to a frightened body's need.", tags = { "spell:Healing_Touch" } },
      { "Rebirth was the wild's answer to a death that came before the fighting was done, and I learned to call on it.", tags = { "spell:Rebirth" } },
      { "Immolate offered the satisfying prospect of keeping a foe burning while I stayed out of reach.", tags = { "spell:Immolate" } },
      { "I learned Immolate, a fire I would never welcome at my own hearth.", tags = { "spell:Immolate" } },
      { "With Life Tap learned, I could feed my magic at the cost of my own blood.", tags = { "spell:Life_Tap" } },
